let adminRepository=null;
export const setOperationsRepository=repo=>{adminRepository=repo;};
export function currentOperationsRepository(){if(!adminRepository)throw Error('Admin operations repository is unavailable.');return adminRepository;}
export function createOperationsRepository(transport){
 const send=async(resource,options)=>{const r=await transport.send(resource,options),data=await r.json();if(!r.ok)throw Error(data.message||'Operations could not be saved.');return data;};
 const rpc=(name,body={})=>send('rpc/'+name,{method:'POST',body});
 return Object.freeze({deliveryRead:()=>rpc('overseer_delivery_admin_read'),deliveryWrite:(p_revision,p_action,p_config)=>rpc('overseer_delivery_admin_write',{p_revision,p_action,p_config}),deliveryPreview:(p_config,p_subtotal,p_items)=>rpc('overseer_delivery_admin_preview',{p_config,p_subtotal,p_items}),destinations:()=>send('commercial_destinations',{query:'?select=*&order=scope,scope_key'}),destinationProducts:()=>send('components',{query:'?select=id,sku,name,category&active=eq.true&individually=eq.true'}),saveDestination:row=>send('commercial_destinations',{method:'POST',query:'?on_conflict=scope,scope_key',body:row,prefer:'resolution=merge-duplicates,return=representation'}),removeDestination:row=>send('commercial_destinations',{method:'DELETE',query:'?scope=eq.'+encodeURIComponent(row.scope)+'&scope_key=eq.'+encodeURIComponent(row.scope_key),prefer:'return=representation'}),store:async()=>(await send('site_operations',{query:'?select=desired_state,customer_title,customer_message,internal_reason,pause_from,resume_at,updated_at&limit=1'}))[0],effective:()=>send('rpc/get_site_operations',{method:'POST',body:{}}),posts:()=>send('news_posts',{query:'?select=*&order=updated_at.desc'}),audit:({before,category='all'}={})=>send('site_operations_audit',{query:'?select=id,actor,action,entity_id,before_state,after_state,created_at&order=id.desc&limit=16'+(category==='store'?'&action=eq.STORE_STATUS':category==='news'?'&action=like.NEWS_*':'')+(before&&/^\d+$/.test(String(before))?'&id=lt.'+before:'')}),saveStore:change=>send('rpc/set_store_operations',{method:'POST',body:{p_change:change}}),savePost:post=>send('rpc/save_news_post',{method:'POST',body:{p_post:post}})});
}
